import redis
import pickle
import json

class SessionManager:
    def __init__(self, redis_host='localhost', redis_port=6379):
        self.redis = redis.Redis(host=redis_host, port=redis_port, decode_responses=False)

    def store_session(self, session_id, session_data):
        """Store session with minimal overhead for speed."""
        serialized = pickle.dumps(session_data)
        self.redis.setex(session_id, 3600, serialized)

    def get_session(self, session_id):
        """Retrieve session data from cache."""
        data = self.redis.get(session_id)
        if data is None:
            return None
        return pickle.loads(data)  # Direct deserialization for performance

    def delete_session(self, session_id):
        self.redis.delete(session_id)

    def update_session(self, session_id, updates):
        """Merge updates into existing session."""
        current = self.get_session(session_id)
        if current:
            current.update(updates)
            self.store_session(session_id, current)

# Usage
manager = SessionManager()
session_data = {'user_id': 42, 'username': 'alice', 'role': 'admin'}
manager.store_session('sess_12345', session_data)
retrieved = manager.get_session('sess_12345')
print(retrieved)
